 const draft={id:'course-proven-old',materialId:'reading-one',taskId:'reading',courseDay:1,mode:'practice',kind:'original',parentId:null,startedAt:'2026-10-24T11:50:00.000Z',activeSeconds:10,exposureAtStart:'seen',answers:{q1:'Red'},userEvidence:{q1:'original source'},text:'original text',transcript:'',audioAvailable:false,audioCompleted:false,transcriptViewed:false,interrupted:false,assistance:{hint:false,answer:false,ai:false},media:[]},raw=JSON.stringify({schema:1,day:1,exposures:{},drafts:{[draft.id]:draft},queue:{}}),storage=new Map([['ielts52-course-player-v1',raw]]);
