 await f.win.IELTSTodayNavigation.resumeDraft(draft.id);const saved=JSON.parse(f.map.get(f.win.IELTSCoursePlayer.KEY)).drafts[draft.id];assert.equal(saved.materialBinding.gradingPolicy,'legacy-normalized-v1');assert.deepEqual(saved.answers,draft.answers);assert.deepEqual(saved.userEvidence,draft.userEvidence);assert.equal(saved.text,draft.text);assert.equal(saved.activeSeconds,draft.activeSeconds);assert.deepEqual(saved.media,draft.media);assert.equal(saved.startedAt,draft.startedAt);
