 let exported;const f=fixture({}, {recordTransform:input=>{const artifact=JSON.parse(input.answer);delete artifact.materialBinding;return{...input,answer:JSON.stringify(artifact)};},window:{IELTSMediaLibrary:{download:(blob,name)=>{exported={blob,name};}}}});await new Promise(resolve=>setImmediate(resolve));await f.win.IELTSTodayNavigation.resumeNext('reading',f.mat.id);
 const input=optionInputs(f,'q1').find(item=>item.value==='red');input.checked=true;await input.fire('change');f.advance(1000);await f.nodes.get('courseSubmit').fire('click');const original=JSON.stringify(f.records()[0]);assert.equal(f.records()[0].evaluation.score,1);
 f.mat.version='2';f.mat.questions=[{id:'new-question',type:'single',prompt:'A new replacement question',options:['new','other'],answers:['other']}];await f.win.IELTSTodayNavigation.showLatestRecord('reading',f.mat.id);
